const parseApiResponse=async(response:Response)=>{const text=await response.text();let data:any={};try{data=text?JSON.parse(text):{}}catch{data={text}}if(!response.ok)throw new Error(data?.error||data?.message||`Request failed (${response.status})`);return {data}};
const api={post:async(path:string,body?:unknown)=>{const {data:{session}}=await supabase.auth.getSession();if(!session)throw new Error('AUTH_REQUIRED');return parseApiResponse(await fetch(path,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${session.access_token}`},body:JSON.stringify(body??{})}))}};
